import {icon} from './icons.js';
import {engineGuide} from './engine-guide.js';
import {outputName as brandedName} from './naming.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let base=localStorage.getItem('waraq-engine')||'',token='',caps=null;
export const engineOperations={cadToPdf:['CAD drawing to PDF','رسم CAD إلى PDF'],optimize:['Optimize PDF (lossless)','تحسين PDF (بدون فقد)'],fixArabic:['Fix Arabic text','إصلاح النص العربي'],sign:['Certificate signature','توقيع بالشهادة'],ocr:['Searchable PDF OCR','PDF قابل للبحث'],repair:['Repair PDF','إصلاح PDF'],protect:['Password protection','الحماية بكلمة مرور'],unlock:['Unlock PDF','فتح PDF'],officeToPdf:['Office to PDF','أوفيس إلى PDF'],pdfToWord:['PDF to Word','PDF إلى Word'],pdfToExcel:['PDF to Excel','PDF إلى Excel'],pdfToPowerPoint:['PDF to PowerPoint','PDF إلى PowerPoint'],pdfa:['Archive as PDF/A','أرشفة PDF/A'],validateSignature:['Inspect digital signatures','فحص التوقيعات الرقمية'],flatten:['Flatten forms','تسطيح النماذج'],redactText:['Redact matching text','تنقيح نص مطابق'],ocrText:['AI document extraction','استخراج المستند بالذكاء الاصطناعي']};
function url(path){return (base||location.origin)+path;}
function headers(){return {'X-Waraq-Client':'1',...(token?{Authorization:'Bearer '+token}:{})};}
function normalize(value){if(!value.trim())return '';const u=new URL(value);if(u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('Use origin only');if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(u.hostname)))throw Error('HTTPS required');return u.origin;}
export function refreshEngineStatus(ctx){const e=document.querySelector('#engineStatus');if(e)e.textContent=caps?ctx.t('Engine connected','المحرك متصل'):ctx.t('Not connected','غير متصل');ctx.onCapabilities?.();}
/** Used by batch processing: sends one file to the connected engine and returns {bytes, filename}. */
export async function processWithEngine(id,bytes,filename,options={},signal){const response=await engineRequest(id,bytes,filename,options,signal);if(!response.ok){const e=await response.json().catch(()=>({}));throw Error(e.error||'HTTP '+response.status);}const disposition=response.headers.get('content-disposition')||'';let name=null;try{const encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1];name=encoded?decodeURIComponent(encoded):null;}catch{}return{bytes:new Uint8Array(await response.arrayBuffer()),filename:(name||filename).replace(/[<>:"/\\|?*\x00-\x1f]/g,'_')};}
/** Sends a document to the engine as raw bytes; options travel base64-encoded in a header when small. */
async function engineRequest(id,bytes,filename,options={},signal){
 const json=JSON.stringify(options||{});
 if(json.length<6000){const response=await fetch(url('/api/process/'+id),{method:'POST',headers:{...headers(),'Content-Type':'application/octet-stream','X-Waraq-Filename':encodeURIComponent(filename),'X-Waraq-Options':btoa(unescape(encodeURIComponent(json)))},body:bytes,signal,credentials:'omit'});if(response.status!==415)return response;}
 let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));
 return fetch(url('/api/process/'+id),{method:'POST',headers:{...headers(),'Content-Type':'application/json'},body:JSON.stringify({filename,data:btoa(binary),options}),signal,credentials:'omit'});
}
/** Desktop only: MuPDF draws heavy pages as images. Never used for a remote server, so no document is uploaded. */
export function engineRendering(){return !!caps?.rendering&&window.waraqDesktop?.isDesktop===true;}
export async function renderDocId(bytes){const r=await fetch(url('/api/render/doc'),{method:'POST',headers:{...headers(),'Content-Type':'application/octet-stream'},body:bytes,credentials:'omit'});if(!r.ok)throw Error('render upload failed');return (await r.json()).id;}
export function renderUrl(id,page,width){return url('/api/render/'+id+'/'+page+'?w='+Math.round(width));}
/** Deep zoom: one region of a page, s = pixels per PDF point, region in pixels at that scale. */
export function renderTileUrl(id,page,s,x,y,w,h){return url(`/api/render/${id}/${page}/tile?s=${s}&x=${x}&y=${y}&w=${w}&h=${h}`);}
/** Heavy = very large pages or a lot of data per page (typical of CAD exports). */
export function isHeavy(byteLength,pageCount,maxPageArea){return byteLength/Math.max(1,pageCount)>1.5*1024*1024||maxPageArea>1.6e6;}
export function engineAvailable(id){return !!caps?.operations?.[id]?.available;}
export async function refreshEngines(ctx){try{const r=await fetch(url('/api/capabilities'),{headers:headers(),signal:AbortSignal.timeout(window.waraqDesktop?.isDesktop?30000:8000)/* the bundled engine checks LibreOffice on a cold start */,cache:'no-store',credentials:'omit'});if(!r.ok)throw Error('Unavailable');const result=await r.json();if(!result.operations||result.version!==1)throw Error('Not a Waraq engine');caps=result;}catch{caps=null;}refreshEngineStatus(ctx);return caps;}
// Grouped by what the user wants to do; engine ids are shown with friendly names.
const FAMILIES=[
 [['ocr','fixArabic','ocrText','pdfa'],'Text recognition','التعرف على النصوص'],
 [['officeToPdf','pdfToWord','pdfToExcel','pdfToPowerPoint','cadToPdf'],'Conversion','التحويل'],
 [['sign','validateSignature','protect','unlock','redactText','eraseAreas'],'Security and signatures','الأمان والتوقيعات'],
 [['optimize','repair','flatten'],'Optimize and repair','التحسين والإصلاح']
];
const ENGINE_NAMES={qpdf:'qpdf',mutool:'MuPDF',waraqocr:['Built-in OCR','OCR المدمج'],ocrmypdf:'OCRmyPDF',libreoffice:'LibreOffice',libredwg:'LibreDWG',wincms:['Windows signing','توقيع ويندوز'],stirling:['Stirling server','خادم Stirling'],ocrbase:['AI text server','خادم النصوص الذكي']};
export function openEngines(ctx){
 const {t,modal}=ctx,desktop=window.waraqDesktop?.isDesktop===true;
 const engineName=(id)=>{const n=ENGINE_NAMES[id];return Array.isArray(n)?t(...n):(n||id);};
 modal(t('Processing engines','محركات المعالجة'),`<div class="eng-status" id="engStatus" role="status"></div><p id="engineMessage" class="eng-msg" role="status"></p><div id="engineList" class="eng-groups"></div>
  <details class="eng-connect"${desktop||caps?'':' open'}><summary>${desktop?t('Advanced: use another Waraq server','متقدم: استخدام خادم ورق آخر'):t('Connect to a Waraq server','الاتصال بخادم ورق')}</summary>
   <p class="pw-muted">${t('No document is sent when you test a connection.','لا يُرسل أي مستند عند اختبار الاتصال.')}</p>
   <label>${t('Server address (leave empty for this website)','عنوان الخادم (اتركه فارغاً لهذا الموقع)')}<input id="engineUrl" type="url" dir="ltr" placeholder="https://pdf.example.com" value="${escape(base)}"></label>
   <label>${t('Access token (kept for this session only)','رمز الوصول (يُحفظ لهذه الجلسة فقط)')}<input id="engineToken" type="password" dir="ltr" autocomplete="off" value="${escape(token)}"></label>
   <div class="advanced-actions"><button class="primary" id="connectEngine">${t('Connect and check','اتصال وفحص')}</button><button id="disconnectEngine">${t('Disconnect','قطع الاتصال')}</button></div>
  </details>${engineGuide(t,caps)}`);
 const render=()=>{
  const status=document.querySelector('#engStatus'),list=document.querySelector('#engineList');if(!status||!list)return;
  const ids=Object.keys(engineOperations),ready=ids.filter(engineAvailable).length;
  const where=desktop?t('Engines on this computer','المحركات على هذا الجهاز'):caps?`${t('Connected to','متصل بـ')} <b dir="ltr">${escape(new URL(base||location.origin).host)}</b>`:t('No engine connected','لا يوجد محرك متصل');
  status.className='eng-status '+(!caps?'is-off':ready===ids.length?'is-ok':'is-partial');
  status.innerHTML=`<span class="eng-dot" aria-hidden="true"></span><div><b>${where}</b><span>${caps?t(`${ready} of ${ids.length} tools ready`,`${ready} من ${ids.length} أداة جاهزة`):t('Tools on your device keep working without an engine.','أدوات جهازك تعمل دون محرك.')}</span></div><button type="button" class="pw-icon" id="engRefresh" title="${t('Check again','إعادة الفحص')}" aria-label="${t('Check again','إعادة الفحص')}">${icon('rotate')}</button>`;
  document.querySelector('#engRefresh').onclick=async()=>{const m=document.querySelector('#engineMessage');m.textContent=t('Checking engines…','جارٍ فحص المحركات…');await fetch(url('/api/capabilities?refresh=1'),{headers:headers(),cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(30000)}).catch(()=>{});await refreshEngines(ctx);m.textContent='';render();};
  const grouped=new Set(FAMILIES.flatMap(f=>f[0])),other=ids.filter(id=>!grouped.has(id));
  list.innerHTML=[...FAMILIES,[other,'Other','أخرى']].map(([members,en,ar])=>{const items=members.filter(id=>engineOperations[id]);if(!items.length)return '';
   return `<section class="eng-group"><h4>${t(en,ar)}</h4><ul>${items.map(id=>{const ok=engineAvailable(id);return `<li><span>${t(...engineOperations[id])}</span><span class="eng-chip${ok?' is-ok':''}">${ok?t('Ready','جاهز')+' · '+escape(engineName(caps.operations[id].engine)):t('Needs an engine','يحتاج محركاً')}</span></li>`;}).join('')}</ul></section>`;}).join('');
 };
 render();
 document.querySelector('#connectEngine').onclick=async()=>{const b=document.querySelector('#connectEngine'),m=document.querySelector('#engineMessage');try{const next=normalize(document.querySelector('#engineUrl').value);base=next;token=document.querySelector('#engineToken').value.trim();caps=null;b.disabled=true;m.textContent=t('Checking engine…','جارٍ فحص المحرك…');await refreshEngines(ctx);if(caps){localStorage.setItem('waraq-engine',base);m.textContent=t('Connected.','تم الاتصال.');}else m.textContent=t('Could not connect. Check the address and token, and that the server allows this website.','تعذر الاتصال. تحقق من العنوان والرمز، ومن أن الخادم يسمح لهذا الموقع.');render();}catch{m.textContent=t('Enter an https:// address, or http://127.0.0.1 with a port, without a path.','أدخل عنواناً يبدأ بـ https://‎ أو http://127.0.0.1 مع المنفذ ودون مسار.');}finally{b.disabled=false;}};
 document.querySelector('#disconnectEngine').onclick=()=>{base='';token='';caps=null;localStorage.removeItem('waraq-engine');refreshEngineStatus(ctx);document.querySelector('#engineUrl').value='';document.querySelector('#engineToken').value='';document.querySelector('#engineMessage').textContent=t('Disconnected. Tools on your device still work.','تم قطع الاتصال. أدوات جهازك تعمل كالمعتاد.');render();};
}
export async function runEngine(id,ctx){const {t,modal}=ctx;await refreshEngines(ctx);
 if(!engineAvailable(id)&&window.waraqDesktop?.packs){const packs=await import('./packs-ui.js');if(await packs.offerPack(ctx,id,async()=>{await refreshEngines(ctx);runEngine(id,ctx);}))return;}
 if(!engineAvailable(id)){openEngines(ctx);document.querySelector('#engineMessage').textContent=t('This tool needs a connected and configured engine.','تحتاج هذه الأداة إلى محرك متصل ومهيأ.');return;}
 const fileNeeded=['officeToPdf','unlock','repair','validateSignature','flatten','cadToPdf'].includes(id);
 if(!fileNeeded&&!ctx.hasPages()){ctx.msg('Open a PDF first.','افتح ملف PDF أولاً.');return;}
 const target=new URL(base||location.origin).origin;
 const fields=id==='sign'?`<p class="engine-warn">${t('Sign last: any later change to the document breaks the signature.','وقّع في النهاية: أي تعديل لاحق على المستند يُبطل التوقيع.')}</p><label>${t('Certificate','الشهادة')}<select id="signSource"><option value="pfx">${t('Certificate file (.pfx / .p12)','ملف شهادة (‎.pfx / .p12‎)')}</option>${(caps?.operations?.sign?.certificates||[]).map(c=>`<option value="store:${escape(c.thumbprint)}" data-subject="${escape(c.subject)}">${escape(c.subject)} — ${escape(c.issuer)} (${escape(c.notAfter)})</option>`).join('')}</select></label><label>${t('Certificate file (only for the file option)','ملف الشهادة (لخيار الملف فقط)')}<input id="signFile" type="file" accept=".pfx,.p12,application/x-pkcs12"></label><label>${t('Certificate password','كلمة مرور الشهادة')}<input id="signPassword" type="password" autocomplete="off"></label><label>${t('Reason (optional)','السبب (اختياري)')}<input id="signReason" maxlength="200"></label><label>${t('Location (optional)','المكان (اختياري)')}<input id="signLocation" maxlength="200"></label><label class="pw-check"><input type="checkbox" id="signVisible" checked> ${t('Show a signature box on the last page','أظهر مربع التوقيع في الصفحة الأخيرة')}</label><p class="pw-muted">${t('USB tokens and ID cards may ask for their PIN in a Windows window.','قد تطلب مفاتيح USB وبطاقات الهوية رمز PIN في نافذة من ويندوز.')}</p>`:(id==='protect'||id==='unlock')?`<label>${t(id==='protect'?'New document password':'Current document password',id==='protect'?'كلمة مرور جديدة':'كلمة مرور المستند الحالية')}<input id="enginePassword" type="password" autocomplete="new-password" required></label>`:id==='redactText'?`<label>${t('Text to permanently remove','النص المراد إزالته نهائياً')}<input id="engineRedact" maxlength="1000"></label>`:id==='ocr'?`<label>${t('OCR language','لغة OCR')}<select id="engineLanguage"><option value="ara+eng">العربية + English</option><option value="ara">العربية</option><option value="eng">English</option></select></label>`:'';
 modal(t(...engineOperations[id]),`<p>${t('This operation sends your document to the following engine:','ترسل هذه العملية المستند إلى المحرك التالي:')} <strong dir="ltr">${escape(target)}</strong>. ${t('Only proceed if you trust this server.','تابع فقط إذا كنت تثق بهذا الخادم.')}</p>${fileNeeded?`<label>${t('Choose source file','اختر الملف الأصلي')}<input id="engineFile" type="file" accept="${id==='cadToPdf'?'.dwg,.dxf':id==='officeToPdf'?'.doc,.docx,.odt,.xls,.xlsx,.ods,.ppt,.pptx,.odp':'.pdf'}"></label>`:`<p>${t('Uses the currently selected pages, or all workspace pages if none are selected.','يستخدم الصفحات المحددة أو جميع صفحات مساحة العمل إن لم تحدد شيئاً.')}</p>`}${fields}<p id="engineProcessMessage" role="status"></p><div class="advanced-actions"><button class="primary" id="engineRun">${t('Send to engine and process','إرسال إلى المحرك ومعالجة')}</button><button id="engineCancel" hidden>${t('Cancel request','إلغاء الطلب')}</button></div>`);
 document.querySelector('#engineRun').onclick=async()=>{const button=document.querySelector('#engineRun'),m=document.querySelector('#engineProcessMessage'),cancel=document.querySelector('#engineCancel');let input= fileNeeded?document.querySelector('#engineFile').files[0]:null;if(fileNeeded&&!input){m.textContent=t('Choose a file first.','اختر ملفاً أولاً.');return;}if(input?.size>(caps?.limits?.inputBytes||50*1024*1024)){m.textContent=t('This file is larger than the engine accepts.','هذا الملف أكبر مما يقبله المحرك.');return;}
 const options={};if(id==='sign'){const src=document.querySelector('#signSource').value;options.mode=src.startsWith('store:')?'store':'pfx';if(options.mode==='store'){options.thumbprint=src.slice(6);options.signerName=document.querySelector('#signSource').selectedOptions[0].dataset.subject||'';}else{const f=document.querySelector('#signFile').files[0];if(!f){m.textContent=t('Choose your certificate file.','اختر ملف الشهادة.');return;}if(f.size>290000){m.textContent=t('This certificate file is too large.','ملف الشهادة كبير جداً.');return;}const u=new Uint8Array(await f.arrayBuffer());let b='';for(let i=0;i<u.length;i+=32768)b+=String.fromCharCode(...u.subarray(i,i+32768));options.pfx=btoa(b);}options.password=document.querySelector('#signPassword').value;options.reason=document.querySelector('#signReason').value.trim();options.location=document.querySelector('#signLocation').value.trim();options.visible=document.querySelector('#signVisible').checked;}if(['protect','unlock'].includes(id)){options.password=document.querySelector('#enginePassword').value;if(!options.password){m.textContent=t('Enter a password.','أدخل كلمة مرور.');return;}}if(id==='ocr')options.language=document.querySelector('#engineLanguage').value;if(id==='redactText'){options.text=document.querySelector('#engineRedact').value.trim();if(!options.text)return;}
 const controller=new AbortController();const close=()=>controller.abort();document.querySelector('#dialog').addEventListener('close',close,{once:true});cancel.hidden=false;cancel.onclick=close;button.disabled=true;m.textContent=t('Processing with the engine…','جارٍ المعالجة بالمحرك…');
 try{const bytes=input?new Uint8Array(await input.arrayBuffer()):await ctx.getBytes();let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const timer=setTimeout(()=>controller.abort(),960000);let response;try{response=await fetch(url('/api/process/'+id),{method:'POST',headers:{...headers(),'Content-Type':'application/json'},body:JSON.stringify({filename:input?.name||ctx.filename()+'.pdf',data:btoa(binary),options}),signal:controller.signal,credentials:'omit'});}finally{clearTimeout(timer);}if(!response.ok){const e=await response.json().catch(()=>({}));throw Error(e.error||'Engine could not process this file');}const type=response.headers.get('content-type')||'application/octet-stream';const disposition=response.headers.get('content-disposition')||'';let outputName;const encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1];try{outputName=encoded?decodeURIComponent(encoded):null;}catch{}outputName ||= disposition.match(/filename="([^"]+)"/)?.[1]||brandedName(input?.name||ctx.filename(),id,type.includes('json')?'json':type.includes('text')?'txt':'pdf');outputName=outputName.replace(/[<>:"/\\|?*\x00-\x1f]/g,'_');if(['sign'].includes(id))ctx.downloadOnly?.();await ctx.download(new Uint8Array(await response.arrayBuffer()),outputName,type);m.textContent=ctx.lastDelivery==='applied'?t('Applied to your open document. Undo is available.','طُبّقت النتيجة على المستند المفتوح. يمكنك التراجع.'):t('Result downloaded.','تم تنزيل النتيجة.');}catch(e){m.textContent=e.name==='AbortError'?t('Request cancelled. The server may finish an already-started job before cleanup.','تم إلغاء الطلب. قد يكمل الخادم مهمة بدأت بالفعل قبل التنظيف.'):t('Processing failed: ','فشلت المعالجة: ')+e.message;}finally{button.disabled=false;cancel.hidden=true;document.querySelector('#dialog').removeEventListener('close',close);}
 };
}

